	FUNCTION DATA_LNO_SEQ(
		I_IF_PROC_TYP IN VARCHAR2
	)RETURN VARCHAR2
	 DETERMINISTIC IS
	BEGIN
		IF (I_IF_PROC_TYP = PO_SEND) THEN
			RETURN NULL;
		ELSIF (I_IF_PROC_TYP = PO_PRMS_RECV) THEN
			RETURN 'MSS_POPRMSRECVIF';
		ELSIF (I_IF_PROC_TYP = SHIP_ACT_RECV) THEN
			RETURN 'MSS_EDISHIPACTRECVIF';
		ELSIF (I_IF_PROC_TYP = ACCPT_SEND) THEN
			RETURN NULL;
