	FUNCTION IS_PCM(
		I_IF_PROC_TYP IN VARCHAR2
	)RETURN CHAR
	 DETERMINISTIC IS
	BEGIN
		IF (I_IF_PROC_TYP = PO_SEND) THEN
			RETURN '0';
